private final Response decryptResponseBody(Response response, EncryptionUtils.EncryptResult encryptResult, String requestPath) {
    ResponseBody responseBodyBody = response.body();
    if (responseBodyBody == null) {
        return response;
    }
    try {
        String strString = responseBodyBody.string();
        LogUtil.INSTANCE.d(TAG, "<<< Decrypting response for " + requestPath);
        return response.newBuilder().body(ResponseBody.INSTANCE.create(DecryptUtils.INSTANCE.getRealBody(strString, encryptResult, requestPath), responseBodyBody.contentType())).build();
    } catch (Exception e) {
        LogUtil.INSTANCE.e(TAG, "Decryption failed for " + requestPath + ": " + e.getMessage());
        return response;
    }
}
